const subject = @import("subject");
pub export fn agent_observe(index: u32) u64 {
    const inputs = [_][]const u8{ &.{0}, &.{127}, &.{128,1}, &.{128,128,1}, &.{255,255,255,255,255,255,255,255,255,1}, &.{128,0}, &.{128}, &.{255,255,255,255,255,255,255,255,255,2} };
    if (index >= inputs.len) return 999;
    var reader: subject.Reader = .{ .input = inputs[index] };
    return reader.natural() catch |err| switch (err) { error.NonCanonical => 1001, error.Truncated => 1002, error.InvalidLength => 1003, else => 999 };
}
